const fs = require('fs');
const path = require('path');

const modelsDir = path.join(__dirname, '..', 'assets', 'models');
const jsDir = path.join(__dirname, '..', 'js');

// 1. Bundle Species
const speciesMap = {
  'tiger': 'tiger.glb',
  'peacock': 'peacock.glb',
  'wild_boar': 'boar.glb',
  'boar': 'boar.glb',
  'flying_squirrel': 'squirrel.glb',
  'squirrel': 'squirrel.glb'
};
const speciesObj = {};

for (const [key, filename] of Object.entries(speciesMap)) {
  const filePath = path.join(modelsDir, filename);
  if (fs.existsSync(filePath)) {
    const data = fs.readFileSync(filePath);
    speciesObj[key] = data.toString('base64');
  } else {
    console.error(`✗ Missing species model: ${filePath}`);
  }
}

const speciesCode = `// Autogenerated 3D Species Models (Zero CORS Risk, Offline & Hostinger Ready)
var SPECIES_MODELS_BASE64 = ${JSON.stringify(speciesObj, null, 2)};
if (typeof window !== "undefined") {
  window.SPECIES_MODELS_BASE64 = SPECIES_MODELS_BASE64;
}
if (typeof module !== "undefined" && module.exports) {
  module.exports = SPECIES_MODELS_BASE64;
}
`;

fs.writeFileSync(path.join(jsDir, 'species-model-data.js'), speciesCode, 'utf8');
console.log('✓ Created js/species-model-data.js with keys:', Object.keys(speciesObj));

// 2. Bundle Threats
const threatMap = {
  'chemical_waste': 'chemical_waste.glb',
  'forest_fire': 'forest_fire.glb',
  'illegal_logging': 'illegal_logging.glb',
  'plastic_trash': 'plastic_trash.glb',
  'wire_snare': 'wire_snare.glb'
};
const threatsObj = {};

for (const [key, filename] of Object.entries(threatMap)) {
  const filePath = path.join(modelsDir, filename);
  if (fs.existsSync(filePath)) {
    const data = fs.readFileSync(filePath);
    threatsObj[key] = data.toString('base64');
  } else {
    console.error(`✗ Missing threat model: ${filePath}`);
  }
}

const threatsCode = `// Autogenerated 3D Threat Models (Zero CORS Risk, Offline & Hostinger Ready)
var THREATS_MODELS_BASE64 = ${JSON.stringify(threatsObj, null, 2)};
if (typeof window !== "undefined") {
  window.THREATS_MODELS_BASE64 = THREATS_MODELS_BASE64;
}
if (typeof module !== "undefined" && module.exports) {
  module.exports = THREATS_MODELS_BASE64;
}
`;

fs.writeFileSync(path.join(jsDir, 'threats-model-data.js'), threatsCode, 'utf8');
console.log('✓ Created js/threats-model-data.js with keys:', Object.keys(threatsObj));
